    ctx.lineWidth = Math.max(1, font * 0.07); ctx.strokeStyle = '#d5bc98'; ctx.stroke();
    ctx.fillStyle = '#9b2a3a';
    ctx.fillText(text, 0, font * 0.04);
    ctx.restore();
