    if (P.cameo) drawCameo(R, ctx, v, P, state);
    if (P.tassels) drawTassels(R, ctx, v, P, state);
    if (P.butterfly) drawEmbroidery(R, ctx, v, P, state);
    if (P.gate) drawGate(R, ctx, v, P, state);
  }

  function air(R, ctx, v, state) {
